// crush-guard-writes-007-host-crush-config-reported: A host project's own crush config declaring permissions or hooks must be reported before a crush turn, and the turn must still write only inside its write roots
func TestCrushGuardWrites007HostCrushConfigReported(t *testing.T) {
	s := scenarios.New(t, "crush-guard-writes-007-host-crush-config-reported")
	s.Given(`the "build-tests-host-crush-config" project tree`)
	s.And(`the System Architect answers "1" to every question`)
	s.When(`the System Architect runs "build tests --fix"`)
	s.Then(`the command exits with code 0`)
	s.And(`stdout matches level=WARN msg="Host crush config merges over the engine's generated config" file=\S*/\.crush\.json declares="\[permissions hooks\]" note="engine write-guard hook still applies"`)
	s.And(`the file "tests/mcp/mcp_test.go" is created`)
	s.And(`every step of scenario "INT-900" in "docs/scenarios.yaml" is matched by a step definition under "tests/mcp/steps"`)
	s.But(`no file outside "tests" and "tmp" changed`)
	s.Done()
}
